head.script:
scwin.contnId;
scwin.objTpCd;
scwin.vCurDate;
scwin.gLdMktTp = js_market;

// alert("js_bond_yn-->"+js_bond_yn);
// 2009.09.01 채권시장인 경우
if (js_bond_yn === "Y") {
    scwin.gLdMktTp = "4";
}

// alert("gLdMktTp-->"+gLdMktTp);

pnl_kclic.hide();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 영문공시제출 오픈시 아래 부분 삭제
        //--------------------------------------------------
        label_28.hide();
        pnl_eng_fil.hide();
        //----------------------------------------------------

        $c.cm.PanelToGroupBox(panel_Top);
        scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
        getContnId = $c.frame.path("../").fn_getContnId;
        scwin.contnId = getContnId();
        if (scwin.contnId !== "input") {
            getSysCode = $c.frame.path("../").fn_getSysCode;
            scwin.objTpCd = getSysCode();
            panel_mkt_gubun.hide();
            if (scwin.objTpCd === "조회(국문)") {
                scwin.objTpCd = "2";
                panel_sel1.hide();
                panel_sel2.show("");
                panel_sel3.hide();
                panel_sel6.hide();
                panel_sel7.hide();
                panel_sel8.hide();
                pnl_valueup.show("");
                rdo_bbs_tp_cd.setDisabled(true);
            } else if (scwin.objTpCd === "처리시스템") {
                scwin.objTpCd = "3";
                panel_sel1.hide();
                panel_sel2.hide();
                panel_sel3.show("");
                panel_sel6.hide();
                panel_sel7.hide();
                panel_sel8.hide();
                if (scwin.gLdMktTp === '9') panel_mkt_gubun.show("");
            } else if (scwin.objTpCd === "제출(영문)시스템") {
                scwin.objTpCd = "6";
                panel_sel1.hide();
                panel_sel2.hide();
                panel_sel3.hide();
                panel_sel6.show("");
                panel_sel7.hide();
                panel_sel8.hide();
                if (scwin.gLdMktTp === '9') panel_mkt_gubun.show("");
            } else if (scwin.objTpCd === "K-CLIC시스템") {
                scwin.objTpCd = "B";
                panel_sel1.hide();
                panel_sel2.hide();
                panel_sel3.hide();
                panel_sel6.hide();
                panel_sel7.show("");
                panel_sel8.hide();
                if (scwin.gLdMktTp === '9') panel_mkt_gubun.show("");
            } else if (scwin.objTpCd === "조회(영문)") {
                scwin.objTpCd = "D";
                panel_sel1.hide();
                panel_sel2.hide();
                panel_sel3.hide();
                panel_sel6.hide();
                panel_sel7.hide();
                panel_sel8.show("");
                if (scwin.gLdMktTp === '9') {
                    panel_mkt_gubun.show("");
                    rdo_mkt_gubun.setDisabled(true);
                }
                pnl_valueup.show("");
                rdo_bbs_tp_cd.setDisabled(true);
            } else {
                scwin.objTpCd = "1";
                panel_sel1.show("");
                panel_sel2.hide();
                panel_sel3.hide();
                panel_sel6.hide();
                panel_sel7.hide();
                panel_sel8.hide();
                if (scwin.gLdMktTp === '9') panel_mkt_gubun.show("");
            }
            await scwin.singleRead();
            gubun.hide();
            // showObj(panel_mkt_gubun,false);

            if (scwin.objTpCd === "1" || scwin.objTpCd === "6") {
                // showObj(panel_mkt_gubun,false);
                rdo_mkt_gubun.setValue(dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD"));
            }
            cmb_chrg_inst.setValue(dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "CHRG_INST_ID"));
        } else {

            // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            await scwin.setIrInfoHeader();
            // edt_SDate.text = cGetToday("yyyymmdd");
            panel_sel1.hide();
            panel_sel2.hide();
            panel_sel3.hide();
            panel_mkt_gubun.hide();
            if (js_market === '9') {
                panel_mkt_gubun.show("");
            }
            btn_delete.hide();
            const today = $c.ut.cGetToday2();
            const nextMonDay = $c.ut.calcMonth(today, 1);
            edt_EDate.setValue(""); // "99991231";

            let mkt_nm = "";
            // mkt_nm = (js_market == "1") ? "(유)" : "(코)";

            // 2009.09.01 채권공시관련
            if (js_bond_yn === "Y") {
                mkt_nm = "(채)";
            } else if (js_market === "1") {
                mkt_nm = "(유)";
            } else if (js_market === "2") {
                mkt_nm = "(코)";
            }
            tbox_user.setValue(mkt_nm + js_dep_nm);
            dts_noticeInfo.setCellData(dts_noticeInfo.getRowPosition(), "WRTR_EMP_NO", js_emp_no);
            if (js_market === "9") {
                rdo_mkt_gubun.setValue("9");
            } else {
                rdo_mkt_gubun.setValue(js_market);
            }
            pnl_valueup.hide();
            rdo_bbs_tp_cd.setValue("03");
            rdo_bbs_tp_cd.setDisabled(true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30401.onpageload" });
    }
};

