///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name singleRead
 * @description 공지사항 개별조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.singleRead = async function() {
    // 공지사항 개별조회

    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/NoticeContent.do",
        ref : "dts_NoticeContentSingle,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name update
 * @description 공지사항 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // 공지사항 수정

    // 이메일 필수입력 제거(YSH, 2008/08/25)
    /*
    if(tbox_email.value=="" || tbox_email.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "이메일") );
    	tbox_email.focus();
    	return;
    }
     */
    if ("" !== tbox_email.getValue()) {
        let a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a === tbox_email.getValue().length - 1) {
            await $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.setValue("");
            tbox_email.focus();
            return;
        }
    }
    if (!await scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.setValue("");
        tbox_email.focus();
        return false;
    }
    if (scwin.objTpCd === "1") {
        if (rdo_mkt_gubun.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
            rdo_mkt_gubun.focus();
            return;
        }
    }
    if (tbox_password.getValue() === "" || tbox_password.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "비밀번호"));
        tbox_password.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_password, 30, "비밀번호")) {
        tbox_password.setValue("");
        tbox_password.focus();
        return false;
    }
    if (dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "PW") !== tbox_password.getValue()) {
        await $c.win.alert("[비밀번호]를 잘못 입력하셨습니다.");
        tbox_password.setValue("");
        tbox_password.focus();
        return;
    }
    if (edt_SDate.getValue() === "" || edt_SDate.Text.indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "게시물적용시작일자"));
        edt_SDate.focus();
        return;
    }
    if (await scwin.dateCheck() === false) {
        return;
    }
    // if(tbox_title.value=="" || tbox_title.value.indexOf(" ") == "" ) {
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }

    // if(tarea_content.Text =="" || tarea_content.Text.indexOf(" ") == "" ) {
    if (tarea_content.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.Focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    let rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        if (scwin.objTpCd === "1") {
            // 2009.09.01 채권공시 관련 추가
            if (js_bond_yn === "Y") {
                dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", "4");
            } else {
                dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", rdo_mkt_gubun.getValue());
            }
        }

        // 조회(영문)일 , 밸류업일 경우 bbs_tp_cd = 61 이다
        if (scwin.objTpCd === 'D') {
            dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "BBS_TP_CD", "61");
        }

        // 적용 끝일자가 없으면 자동으로 99991231 입력한다.
        if (edt_EDate.getValue() === "") {
            dts_NoticeContentSingle.setCellData(1, "NOTI_END_DD", "99991231");
        }
        dts_NoticeContentSingle.setCellData(1, "CHRG_INST_ID", cmb_chrg_inst.getValue());
        trs_Update.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/NoticeContent.do",
            ref : "dts_NoticeContentSingle,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name save
 * @description 공지사항 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 공지사항 등록

    if (check1.checked === false &&
        check2.checked === false &&
        check3.checked === false &&
        check4.checked === false &&
        check5.checked === false &&
        check6.checked === false) {
        await $c.win.alert("[공지대상 시스템]을 선택해주세요");
        return;
    }
    if (check3.checked === true || check4.checked === true || check5.checked === true) {
        if (rdo_mkt_gubun.getValue() === "") {
            await $c.win.alert("[공지대상 시스템]이 제출(국문/영문), K-CLIC 일경우 [시장구분]을 선택해주세요");
            rdo_mkt_gubun.focus();
            return;
        }
    }
    if (check5.checked === true) {
        const ChrgInstId = $c.cp.valueOfIndex(cmb_chrg_inst, "VALUE", cmb_chrg_inst.getSelectedIndex());
        if (ChrgInstId === "") {
            await $c.win.alert("[공지대상 시스템]이 K-CLIC 일경우 담당기관을 선택해주세요");
            cmb_chrg_inst.focus();
            return;
        } else {
            dts_noticeInfo.setCellData(1, "CHRG_INST_ID", ChrgInstId);
        }
    }
    if (check6.checked === true) {
        // 조회(영문)
        if (check5.checked === true || check4.checked === true || check3.checked === true || check2.checked === true || check1.checked === true) {
            await $c.win.alert("[공지대상 시스템]이 조회(영문)일 경우 다른 시스템과 함께 사용할 수 없습니다. ");
            return;
        }
    }
    if (check1.checked === true) {
        // 조회(국문) -- 밸류업
        if (rdo_bbs_tp_cd.getValue() === "60") {
            if (check6.checked === true || check5.checked === true || check4.checked === true || check3.checked === true || check2.checked === true) {
                await $c.win.alert("[공지대상 시스템]이 조회(국문)이면서 밸류업일 경우 다른 시스템과 함께 사용할 수 없습니다. ");
                return;
            }
        }
    }
    // 이메일 필수입력 제거 (YSH, 2008/08/25)
    /*
    if(tbox_email.value=="" || tbox_email.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "이메일") );
    	tbox_email.focus();
    	return;
    }
     */
    if ("" !== tbox_email.getValue()) {
        let a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a === tbox_email.getValue().length - 1) {
            await $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.setValue("");
            tbox_email.focus();
            return;
        }
    }
    if (!await scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.setValue("");
        tbox_email.focus();
        return false;
    }
    if (tbox_password.getValue() === "" || tbox_password.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "비밀번호"));
        tbox_password.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_password, 30, "비밀번호")) {
        tbox_password.setValue("");
        tbox_password.focus();
        return false;
    }
    if (edt_SDate.getValue() === "" || edt_SDate.Text.indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "게시물적용시작일자"));
        edt_SDate.focus();
        return;
    }
    if (await scwin.dateCheck() === false) {
        return;
    }
    // if(tbox_title.value=="" || tbox_title.value.indexOf(" ") == "" ) {
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }

    // if(tarea_content.Text =="" || tarea_content.Text.indexOf(" ") == "" ) {
    if (tarea_content.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.Focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    let rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        // 공시배포
        if (check1.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN1", "Y");
        }
        // 공시제출(국문)
        if (check2.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN2", "Y");
        }
        // 공시처리
        if (check3.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN3", "Y");
        }

        // 공시제출(영문)
        if (check4.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN4", "Y");
        }
        // K-CLIC
        if (check5.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN5", "Y");
        }

        // 조회(영문)
        if (check6.checked === true) {
            dts_noticeInfo.setCellData(1, "CHECK_YN6", "Y");
            dts_noticeInfo.setCellData(1, "BBS_TP_CD", "61");
        }

        // 뒷부분 공백 제거  (YSH, 2008/08/25)
        const passStr = dts_noticeInfo.getCellData(1, "PW");
        dts_noticeInfo.setCellData(1, "PW", $c.ut.trim(passStr));
        // alert(dts_noticeInfo.NameValue(1,"PW"));

        // 적용 끝일자가 없으면 자동으로 99991231 입력한다.
        if (edt_EDate.getValue() === "") {
            dts_noticeInfo.setCellData(1, "NOTI_END_DD", "99991231");
        }

        // 2009.09.01 채권공시 관련 추가
        if (js_bond_yn === "Y") {
            dts_noticeInfo.setCellData(1, "LD_MKT_TP_CD", "4");
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/NoticeContent.do",
            ref : "dts_noticeInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

